"""The viewer's picture, as plain functions: one implementation of the layout for the live window and the offscreen renderer.

Both src/glfw_viewer.py (the live window, which blits the bitmaps with OpenGL) and src/viewer_composite.py (the offscreen renderer behind
replay's "viewer" video mode, which pastes them into an array) draw the same thing: a follow camera behind the robot base, a status panel with
a key legend at the top left, a row of camera tiles along the bottom edge and, in the live window, a banner bar along the top. This module
holds everything that does not depend on where the pixels go: the follow-camera constants and update, the status panel rows and bitmap, the
banner bitmap and the camera tiles and their positions. Every size is given for the live window's reference height of 960 pixels and
multiplied by `scale` (1.0 for the live window, 1080 / 960 for the 1080-pixel video). Positions are returned with the origin at the top
left; the live window converts them to OpenGL's bottom-left origin.

Nothing here imports MuJoCo's rendering or the graphics library framework (GLFW); the functions need only numpy and OpenCV (the camera
object passed to the follow-camera functions is used only through its attributes).
"""

import math
import re

import cv2
import numpy as np

from src.base_control import base_yaw

CAM_DISTANCE = 3.5      # follow camera: distance behind the base in metres [row M127 PENDING David: no decision recorded]
CAM_ELEVATION = -45     # follow camera: angle above the horizon in degrees (negative = looking down) [row M127 PENDING David: no decision recorded]
FOVY_DEG = 90           # vertical field of view of the follow camera in degrees [row M127 PENDING David: no decision recorded]
REFERENCE_HEIGHT = 960  # the live viewer window is 1280 x 960 pixels; sizes below are for this height [row M127 PENDING David: no decision recorded]
BANNER_HEIGHT = 56      # pixels (at scale 1.0) of the banner bar [row M127 PENDING David: no decision recorded]


def hud_key_list(has_teleop, legend_extra=()):
    """Build the key legend shown under the status panel.

    Args:
        has_teleop (bool): Whether the run has webcam teleoperation. If true,
            the F2 entry (switch the arms between manual and teleoperation) is
            included.
        legend_extra (Sequence[tuple[str, str]]): Further (key, label) entries,
            inserted after the F2 entry and before the F3 entry. Defaults to
            an empty tuple.

    Returns:
        list[tuple[str, str]]: (key cap text, short label) pairs, in display
        order. The fixed entries are the base, arm and pedestal keys,
        then F3 (camera images), F4 (snapshot), F5 (log),
        F6 (record video) and Esc (quit).
    """
    return [("Arrows", "drive"), ("Spc", "stop"),
            ("1-8", "L arm +"), ("Q-I", "L arm -"),
            ("A-K", "R arm +"), ("Z-,", "R arm -"),
            ("PgUp/Dn", "pedestal")] + \
        ([("F2", "man/tele")] if has_teleop else []) + \
        list(legend_extra) + \
        [("F3", "cam imgs"), ("F4", "snap"), ("F5", "log"),
         ("F6", "rec video"), ("Esc", "quit")]


def wrap_text(text, max_w, font, fs, thick, max_lines=None):
    """Breaks a text into lines that fit a pixel width, with "..." at the end of the last line if lines had to be dropped.

    Args:
        text (str): The text. Words are kept whole unless one is wider than a line.
        max_w (int): Line width in pixels.
        font (int): OpenCV font id.
        fs (float): OpenCV font scale.
        thick (int): Line thickness in pixels.
        max_lines (int or None): Most lines to return; None means no limit. Defaults to None.

    Returns:
        list[str]: At least one line (an empty text gives one empty line), each at most `max_w` pixels wide.
    """
    width = lambda t: cv2.getTextSize(t, font, fs, thick)[0][0]
    lines, cur = [], ""
    for word in str(text).split():
        while width(word) > max_w:                         # a word wider than a line: cut it
            k = len(word)
            while k > 1 and width(word[:k]) > max_w:
                k -= 1
            if cur:
                lines.append(cur)
                cur = ""
            lines.append(word[:k])
            word = word[k:]
        trial = f"{cur} {word}" if cur else word
        if width(trial) <= max_w:
            cur = trial
        else:
            lines.append(cur)
            cur = word
    lines.append(cur)
    if max_lines is not None and len(lines) > max_lines:
        lines = lines[:max_lines]
        last = lines[-1] + "..."
        while len(last) > 3 and width(last) > max_w:
            last = last[:-4] + "..."
        lines[-1] = last
    return lines


# How a row of the plan block is drawn: (label colour, text colour, font scale factor, highlighted background or None). RGB.
ROW_STYLES = {"normal": ((190, 190, 190), (255, 255, 255), 1.0, None),
              "dim": ((150, 150, 150), (200, 200, 200), 1.0, None),
              "current": ((255, 255, 255), (255, 255, 255), 1.0, (150, 90, 40)),
              "note": ((190, 190, 190), (120, 220, 255), 1.0, None),
              "small": ((150, 150, 150), (170, 170, 170), 0.82, None)}


def text_bitmap(rows, w, label_w, keys=(), scale=1.0, block=(), block_label_w=None):
    """Draw the status panel as an image.

    The panel has one text row per (label, value) pair, then the plan block (rows with a style and a line limit), then the key legend:
    each entry is a key cap icon with a short label, laid out left to right
    and wrapped at the panel width so that the legend uses as little height as
    possible. A value that does not fit the panel width is wrapped onto further lines (at most 4 for a plain row, the block's own
    limit for a block row, then "..."), so nothing is cut off at the panel's edge. The panel height follows from the number of lines.

    Args:
        rows (Sequence[tuple[str, str]]): (label, value) text rows.
        w (int): Panel width in pixels, already multiplied by `scale`.
        label_w (int): Pixel offset of the value column from the left edge,
            already multiplied by `scale`.
        keys (Sequence[tuple[str, str]]): (key, label) legend entries, as
            returned by hud_key_list(). Defaults to an empty tuple (no legend).
        scale (float): Factor applied to every other size (row height, font
            size, line thickness, margins). Defaults to 1.0, which is the live
            viewer.
        block (Sequence[tuple[str, str, str, int]]): Plan block rows (label, value, style key of ROW_STYLES, most lines), from
            panel_block(). Defaults to an empty tuple.
        block_label_w (int or None): Value column offset of the block rows, already multiplied by `scale`; None uses `label_w`.
            Defaults to None.

    Returns:
        numpy.ndarray: Image of shape (height, w, 3), dtype uint8, in
        red-green-blue (RGB) order, top row first.
    """
    S = lambda v: int(round(v * scale))
    line_h, key_h, font = S(20), S(24), cv2.FONT_HERSHEY_SIMPLEX
    fs_row, fs_key, thick = 0.45 * scale, 0.4 * scale, max(1, int(round(scale)))
    layout, x, line = [], S(6), 0
    for key, label in keys:
        kw = cv2.getTextSize(key, font, fs_key, thick)[0][0] + S(8)
        lw = cv2.getTextSize(label, font, fs_key, thick)[0][0]
        if x + kw + S(4) + lw > w - S(6) and x > S(6):
            x, line = S(6), line + 1
        layout.append((key, label, x, line, kw))
        x += kw + S(4) + lw + S(12)
    blw = label_w if block_label_w is None else block_label_w
    items = [(lab, wrap_text(val, w - label_w - S(6), font, fs_row, thick, 4), "normal", label_w) for lab, val in rows]
    if block:
        items.append(None)                                  # a separator line between the rows and the block
        items += [(lab, wrap_text(val, w - blw - S(6), font, fs_row * ROW_STYLES[st][2], thick, ml), st, blw) for lab, val, st, ml in block]
    n_lines = sum(1 if it is None else len(it[1]) for it in items)
    top = line_h * n_lines + S(8)
    h = top + (key_h * (line + 1) + S(6) if keys else 0)
    bmp = np.full((h, w, 3), 45, np.uint8)
    y0 = 0
    for it in items:
        if it is None:
            cv2.line(bmp, (S(6), y0 + S(10)), (w - S(6), y0 + S(10)), (110, 110, 110), thick)
            y0 += line_h
            continue
        lab, lines, st, lw_ = it
        lc, tc, fk, bg = ROW_STYLES[st]
        if bg is not None:
            cv2.rectangle(bmp, (S(2), y0 + S(1)), (w - S(2), y0 + line_h * len(lines) + S(1)), bg, -1)
        for k, ln in enumerate(lines):
            y = y0 + line_h * (k + 1) - S(3)
            if k == 0:
                cv2.putText(bmp, lab, (S(6), y), font, fs_row * fk, lc, thick, cv2.LINE_AA)
            cv2.putText(bmp, ln, (lw_, y), font, fs_row * fk, tc, thick, cv2.LINE_AA)
        y0 += line_h * len(lines)
    if keys:
        cv2.line(bmp, (S(6), top - S(2)), (w - S(6), top - S(2)), (110, 110, 110), thick)
    for key, label, kx, ln, kw in layout:
        y = top + key_h * ln + S(17)
        cv2.rectangle(bmp, (kx, y - S(14)), (kx + kw, y + S(4)), (80, 80, 80), -1)
        cv2.rectangle(bmp, (kx, y - S(14)), (kx + kw, y + S(4)), (200, 200, 200), thick)
        cv2.putText(bmp, key, (kx + S(4), y), font, fs_key, (255, 255, 255), thick, cv2.LINE_AA)
        cv2.putText(bmp, label, (kx + kw + S(4), y), font, fs_key, (150, 220, 150), thick, cv2.LINE_AA)
    return bmp


# What the robot is physically doing in each phase of the status text "<NAV|PICK|PLACE>: <phase> [<status>]" (David 2026-10-28): the panel shows this as the main text and the internal code small
# under it. A phase that appears for both a pick and a place has one entry per kind; HOME is both the move to the home pad pose and the final joint move.
PHASE_ACTIONS = {
    ("NAV", "ARMS"): "Stowing arms", ("NAV", "PEDESTAL"): "Adjusting pedestal height", ("NAV", "CREEP_IN"): "Creeping into position", ("NAV", "DONE"): "Stopped at the bench",
    ("PICK", "OVER"): "Move over beaker", ("PICK", "DOWN"): "Lower to beaker", ("PICK", "IN"): "Close on beaker", ("PICK", "CLOSE"): "Grip beaker",
    ("PICK", "UP"): "Lift beaker", ("PICK", "CHECK"): "Check the beaker is held",
    ("PLACE", "OVER"): "Move over hotplate", ("PLACE", "DOWN"): "Lower to hotplate", ("PLACE", "OPEN"): "Release beaker", ("PLACE", "BACK"): "Back away",
    ("PLACE", "HOME"): "Return to home pose",
}
PHASE_ACTIONS.update({("PICK", "BACK"): "Back away", ("PICK", "HOME"): "Return to home pose", ("PICK", "OPEN"): "Release beaker", ("PLACE", "CLOSE"): "Grip beaker",
                      ("PLACE", "CHECK"): "Check the beaker is held"})


def phase_action(phase, step_text=None):
    """The plain description of what the robot is physically doing, from the status text without its step counter.

    Args:
        phase (str or None): The status text after "<k>/<N> ", e.g. "PICK: OVER [running]", "NAV: DRIVE [running]", "PLAN DONE".
        step_text (str or None): The current plan step's description ("Navigate to the beaker"); its target names the destination of a drive.

    Returns:
        str or None: The description, or None for a status text this table does not know (the panel then shows the code alone).
    """
    text = (phase or "").strip()
    if text.startswith("PLAN DONE"):
        return "All steps done"
    m = re.match(r"(NAV|PICK|PLACE|STEP):\s*(.*?)\s*(?:\[(\w+)\])?$", text)
    if not m:
        return None
    kind, what, status = m.groups()
    if status == "checking":
        return "Checking the result"
    if what.startswith("GROUNDING"):
        return "Finding the object"
    if what.startswith("ASK OPERATOR"):
        return "Waiting for the operator to choose"
    if what.startswith("RETRY"):
        return "Retrying: arm to the home pose"
    if what == "starting":
        return "Holding still, next step starting"
    if kind == "NAV" and what == "DRIVE":
        m2 = re.match(r"(?i)\s*(?:navigate|go|move|drive)\s+to\s+(.+?)\s*$", step_text or "")
        return f"Driving to {m2.group(1)}" if m2 else "Driving to the next position"
    return PHASE_ACTIONS.get((kind, what))


def panel_from_status(static, status):
    """Works out what the plan block shows from the episode status text, for the live window and the video alike.

    The orchestrator's status text is "<k>/<N> <NAV|PICK|PLACE>: <phase> [<status>]" (or "PLAN DONE"); the step index comes from it, so a
    recording needs no extra data besides the static part, and the live window and the video give the same picture.

    Args:
        static (dict or None): What does not change during a run: "instruction" (str or None, the typed instruction), "steps" (list of
            str, the plan's steps in plain language, the planner's descriptions); other keys are ignored. None means no plan block.
        status (str or None): The episode status text.

    Returns:
        dict or None: "instruction", "steps", "index" (0-based index of the current step; the step count once the plan is done), "phase"
        (the status text without the step counter: the internal phase code, shown small), "action" (str or None: the plain description of what the robot is doing, shown
        as the main text, see phase_action()), "now" (str or None: replaces the step text in the NOW row, only while the arms are stowed or the pedestal is adjusted before a drive), or None when
        `static` is None.
    """
    if not static:
        return None
    steps = list(static.get("steps") or [])
    text = (status or "").strip()
    m = re.match(r"(\d+)/(\d+)\s+(.*)$", text)
    if m:
        index, phase = max(0, min(int(m.group(1)) - 1, len(steps))), m.group(3)
    elif text.startswith("PLAN DONE"):
        index, phase = len(steps), text
    else:
        index, phase = 0, text
    step_text = steps[index] if index < len(steps) else None
    action = phase_action(phase, step_text)
    now = action if action and (phase or "").startswith(("NAV: ARMS", "NAV: PEDESTAL")) else None      # the plan step says "Navigate to the beaker" while the arms are still being stowed or the pedestal adjusted: show what the robot does
    return {"instruction": static.get("instruction"), "steps": steps, "index": index, "phase": phase or None, "action": action, "now": now}


def panel_block(panel):
    """The plan block of the status panel as rows for text_bitmap: typed instruction, step k of N, previous / current / next step, phase code.

    Args:
        panel (dict or None): From panel_from_status(), or built by hand for the phases before the robot moves; keys "instruction" (str or
            None: shown in quotes, two lines at most), "note" (str or None: a message such as "Planning...", shown in its own row), "steps"
            (list of str or None: no plan rows when empty), "index" (int, as in panel_from_status), "phase" (str or None: the internal
            phase code, small), "action" (str or None: what the robot is physically doing, plain words, the main text above the code), "now" (str or None: shown in the NOW row instead of the step).

    Returns:
        list[tuple[str, str, str, int]]: Rows (label, value, style key of ROW_STYLES, most lines); empty if `panel` is None.
    """
    if not panel:
        return []
    out = []
    if panel.get("instruction"):
        out.append(("instruction", f'"{panel["instruction"]}"', "normal", 2))
    if panel.get("note"):
        out.append(("status", panel["note"], "note", 4))
    steps = panel.get("steps") or []
    if steps:
        n, i = len(steps), max(0, min(int(panel.get("index") or 0), len(steps)))
        done = i >= n
        out.append(("step", f"{n} of {n} (all done)" if done else f"{i + 1} of {n}", "normal", 1))
        out.append(("previous", steps[i - 1] if i >= 1 else "-", "dim", 2))
        out.append(("NOW", panel.get("now") or ("all steps done" if done else steps[i]), "current", 2))
        out.append(("next", steps[i + 1] if i + 1 < n else "-", "dim", 2))
    if panel.get("action"):
        out.append(("doing", panel["action"], "normal", 2))
    if panel.get("phase"):
        out.append(("code", panel["phase"], "small", 3))
    return out


def setup_follow_camera(cam):
    """Sets the follow camera's fixed distance and elevation and its starting azimuth.

    Args:
        cam (mujoco.MjvCamera): A free camera, already given its defaults by mujoco.mjv_defaultCamera(). Its distance, elevation and azimuth
            are set to CAM_DISTANCE, CAM_ELEVATION and 90 degrees.
    """
    cam.distance, cam.elevation, cam.azimuth = CAM_DISTANCE, CAM_ELEVATION, 90


def update_follow_camera(cam, data, body_id):
    """Points the follow camera at the base and turns it to look along the base's heading.

    Args:
        cam (mujoco.MjvCamera): The free follow camera. Its lookat point and azimuth are written.
        data (mujoco.MjData): Simulation state; the base position is data.xpos[body_id] and the heading comes from base_control.base_yaw().
        body_id (int): Id of the body to follow ("base_link").

    Returns:
        float: The base's yaw in degrees (the camera's azimuth is this plus 90).
    """
    cam.lookat[:] = data.xpos[body_id]
    yaw_deg = math.degrees(base_yaw(data))
    cam.azimuth = yaw_deg + 90
    return yaw_deg


def hud_rows(time_s, base_vel, yaw_deg, position, middle_rows=(), status=None, mode=None, extra_rows=()):
    """Builds the rows of the status panel.

    The first six rows (time, speed, velocity, yaw rate, yaw, position) are the same everywhere. The middle rows are the ones that differ
    between the live window (frame time, keyboard command, recording state) and the video (video rate, applied twist). Then come the episode
    status, the controller mode and any extra rows (the live window's arms row).

    Args:
        time_s (float): Simulation time in seconds.
        base_vel (tuple[float, float, float]): World-frame base velocity (vx, vy in metres per second, wz in radians per second).
        yaw_deg (float): Base yaw in degrees.
        position (Sequence[float]): Base x, y, z in metres.
        middle_rows (Sequence[tuple[str, str]]): (label, value) rows for the backend-specific part. Defaults to none.
        status (str | None): Episode status text for the "episode" row; no row if empty or None. Defaults to None.
        mode (str | None): "auto" or "teleop" for the "controller" row; no row if None. Defaults to None.
        extra_rows (Sequence[tuple[str, str]]): Rows appended at the end. Defaults to none.

    Returns:
        list[tuple[str, str]]: (label, value) rows in display order.
    """
    vx, vy, wz = base_vel
    rows = [("sim time", f"{time_s:.2f} s"),
            ("base speed (m/s)", f"{math.hypot(vx, vy):.2f}"),
            ("base vx, vy (m/s)", f"{vx:+.2f}, {vy:+.2f}"),
            ("yaw rate (rad/s)", f"{wz:+.2f}"),
            ("yaw (deg)", f"{yaw_deg:+.1f}"),
            ("position x, y, z (m)", f"{position[0]:.2f}, {position[1]:.2f}, {position[2]:.3f}")]
    rows += list(middle_rows)
    if status:
        rows.append(("episode", status))
    if mode:
        rows.append(("controller", mode.upper()))
    return rows + list(extra_rows)


def hud_bitmap(rows, keys, scale=1.0, panel=None):
    """Draws the status panel (rows, plan block and key legend) as a bitmap of the standard width.

    Args:
        rows (list[tuple[str, str]]): (label, value) rows, from hud_rows().
        keys (list[tuple[str, str]]): Key legend entries, from hud_key_list(); empty for no legend (the video).
        scale (float): Size factor relative to the live window. Defaults to 1.0.
        panel (dict or None): The plan block (see panel_block()); None draws none. Defaults to None.

    Returns:
        numpy.ndarray: RGB bitmap of shape (height, round(400 * scale), 3), dtype uint8.
    """
    return text_bitmap(rows, int(round(400 * scale)), int(round(180 * scale)), keys, scale, panel_block(panel), int(round(96 * scale)))


def hud_position(scale=1.0, banner_height=0):
    """Gives where the status panel's top-left corner goes, below the banner if there is one.

    Args:
        scale (float): Size factor relative to the live window. Defaults to 1.0.
        banner_height (int): Height in pixels of the banner above the panel. Defaults to 0.

    Returns:
        tuple[int, int]: (left, top) in pixels, origin at the top left.
    """
    margin = int(round(8 * scale))
    return margin, margin + banner_height


def banner_bitmap(text, kind, width):
    """Draws the full-width banner bar: red for a policy request nobody has answered, blue while the operator has control.

    The text is centred and its font is shrunk, down to a limit, until it fits the width.

    Args:
        text (str): The banner text.
        kind (str): "needed" (red bar) or any other value (blue bar).
        width (int): Frame width in pixels.

    Returns:
        numpy.ndarray: RGB bitmap of shape (BANNER_HEIGHT, width, 3), dtype uint8.
    """
    scale = 0.9
    while cv2.getTextSize(text, cv2.FONT_HERSHEY_DUPLEX, scale, 2)[0][0] > width - 40 and scale > 0.4:
        scale -= 0.05
    bar = np.full((BANNER_HEIGHT, width, 3), (200, 30, 30) if kind == "needed" else (30, 90, 200), np.uint8)
    tw, th = cv2.getTextSize(text, cv2.FONT_HERSHEY_DUPLEX, scale, 2)[0]
    cv2.putText(bar, text, ((width - tw) // 2, (BANNER_HEIGHT + th) // 2), cv2.FONT_HERSHEY_DUPLEX, scale, (255, 255, 255), 2, cv2.LINE_AA)
    return bar


TILE_ORDER = ("eagle_cam", "left_wrist_cam", "right_wrist_cam")      # left to right in the row of camera tiles; any other tile (the operator webcam) follows


def order_tiles(tiles):
    """Puts the camera tiles in display order: the eagle camera, then the left hand's view on the left and the right hand's on the right.

    Display only: the policy's cameras keep the order of robot_specs.CAMERA_SPECS (the recordings and the observations depend on it).

    Args:
        tiles (list[tuple]): (camera name, image) pairs in any order.

    Returns:
        list[tuple]: The same pairs, ordered by TILE_ORDER; names not in it keep their relative order after the others.
    """
    rank = {n: i for i, n in enumerate(TILE_ORDER)}
    return sorted(tiles, key=lambda t: rank.get(t[0], len(TILE_ORDER)))


def inset_layout(width, n_tiles, scale=1.0):
    """Gives the size and horizontal positions of the row of camera tiles along the bottom edge.

    Each tile is at most 320 x 240 pixels (times `scale`), shrunk to fit the frame width; the row sits one gap above the bottom edge.

    Args:
        width (int): Frame width in pixels.
        n_tiles (int): Number of tiles in the row.
        scale (float): Size factor relative to the live window. Defaults to 1.0.

    Returns:
        tuple[int, int, int, list[int]]: Tile width, tile height, gap (also the distance from the bottom edge), and the left x of each tile, in
        pixels.
    """
    gap = int(round(8 * scale))
    iw = min(int(round(320 * scale)), (width - gap * (n_tiles + 1)) // n_tiles)
    ih = iw * 3 // 4
    return iw, ih, gap, [gap + k * (iw + gap) for k in range(n_tiles)]


def inset_tile(name, img, iw, ih, scale=1.0):
    """Draws one camera tile: the image scaled to the tile size, with its name in a dark box in the top-left corner.

    Args:
        name (str): The camera's name, written in the corner.
        img (numpy.ndarray | None): RGB image of the camera, any size, row 0 on top; None draws a dark grey tile (no frame delivered yet).
        iw (int): Tile width in pixels.
        ih (int): Tile height in pixels.
        scale (float): Size factor relative to the live window, for the label. Defaults to 1.0.

    Returns:
        numpy.ndarray: RGB bitmap of shape (ih, iw, 3), dtype uint8.
    """
    S = lambda v: int(round(v * scale))
    if img is None:
        small = np.full((ih, iw, 3), 40, np.uint8)
    else:
        small = cv2.resize(img, (iw, ih), interpolation=cv2.INTER_AREA)
    cv2.rectangle(small, (0, 0), (S(len(name) * 9 + 10), S(20)), (45, 45, 45), -1)
    cv2.putText(small, name, (S(5), S(15)), cv2.FONT_HERSHEY_SIMPLEX, 0.5 * scale, (255, 255, 255), max(1, int(round(scale))), cv2.LINE_AA)
    return small
